/** Register Git and per-change diff tabs with the built-in right sidebar. */
import { useMemo, useState, useSyncExternalStore } from 'react'
import type { Context } from '@deepseek-ai/cordis'
import type { PropsRuntime } from '@deepseek-ai/dsh-client-ui-slots'
import type {} from '@deepseek-ai/dsh-client-ui-renderer/client'
import type {} from '@deepseek-ai/dsh-client-ui-sidebar-right/client'
import type {} from '@deepseek-ai/dsh-client-ui-session/client'
import type {} from '@deepseek-ai/dsh-api-session-controller/client'
import type {} from '@deepseek-ai/dsh-api-workspace-controller/client'
import type {} from '@deepseek-ai/dsh-client-ui-workspace/client'
import type {} from '@deepseek-ai/dsh-client-locale/client'
import { IconBranchOutlineRegular, Modal } from '@deepseek-ai/dsh-client-ui-primitives'
import { sessionFileAddress } from '@deepseek-ai/dsh-util-workspace-path'
import { GitView } from './GitView.tsx'
import { DiffTab } from './DiffTab.tsx'
import { api } from './api.ts'
import { attachLocale, en, LOCALE_NS, t, zh } from './locales.ts'
import { parseDiffAddress, diffTitle } from './navigation.ts'
import type { SidebarDiffRef } from './state.ts'
import css from './sidebar.module.css'

export const inject = ['slots', 'locale', 'sidebarRightTabs', 'sessions', 'workspaces', 'uiWorkspace']

function sessionDirectory(session: { cwd?: string; projectionValues?: object } | undefined): string | undefined {
  const values = session?.projectionValues
  return values !== undefined && 'workingDirectory' in values && typeof values.workingDirectory === 'string'
    ? values.workingDirectory : session?.cwd
}

/** Mount independent views; every registration is released on plugin unload. */
export function apply(ctx: Context): void {
  ctx.effect(() => ctx.locale.register(LOCALE_NS, { zh, en }))
  ctx.effect(() => {
    attachLocale(ctx.locale)
    return () => { attachLocale(undefined) }
  })
  ctx.effect(() => ctx.sidebarRightTabs.register({
    id: 'dsh-git-sidebar', kind: 'dsh-git', title: () => t('git'),
    guide: [{ id: 'git', order: 20, title: () => t('git'), description: () => t('gitGuideDesc'), icon: IconBranchOutlineRegular }],
  }))
  ctx.effect(() => ctx.sidebarRightTabs.register({
    id: 'dsh-git-sidebar/diff', kind: 'dsh-git-diff',
    patterns: ['dsh-resource://git-diff/**'],
    canOpen: address => parseDiffAddress(address) !== undefined,
    title: address => diffTitle(parseDiffAddress(address)!.diff),
  }))
  const useLanguage = () => useSyncExternalStore(
    listener => ctx.locale.subscribe(listener), () => ctx.locale.getSnapshot().active,
  )
  function GitBody({ sessionId, useSessions, useTabInfo }: PropsRuntime<'sidebar.right.pane.tab'>) {
    useLanguage()
    const cwd = useSessions(state => sessionDirectory(state.byId[sessionId]))
    const { tab } = useTabInfo()
    const [openDiff, setOpenDiff] = useState<SidebarDiffRef | null>(null)
    const scope = { sessionId, cwd }
    return <><GitView
      scope={scope}
      onOpenDiff={seed => { if (seed.diff !== undefined) setOpenDiff(seed.diff) }}
      onOpenFile={async path => {
        const result = await api.gitPath(scope, path)
        tab.actions.openResource(sessionFileAddress(sessionId, result.path))
      }}
      onPrompt={async text => {
        const scoped = ctx.sessions.scope(sessionId)
        const session = scoped === undefined ? undefined : ctx.sessions.sessionOf(scoped)
        if (session === undefined) throw new Error('session unavailable')
        const handle = session.beginSubmission({ mode: 'queue', text, attachments: [] })
        const result = await session.prompt([{ type: 'text', text }], 'queue', undefined, handle.requestId)
        if (!result.ok) throw new Error(result.error.message)
      }}
      onOpenWorktree={async path => {
        // Returns the existing Workspace. Its session list, not a cwd match, decides reuse:
        // archived sessions and those of a removed Workspace keep their cwd but appear in no Workspace.
        const workspace = await ctx.workspaces.create({ path })
        const { byId } = ctx.sessions.list.getSnapshot()
        const existing = workspace.sessionIds.find(id => byId[id]?.origin !== 'subagent')
        if (existing !== undefined) { ctx.uiWorkspace.openSession(existing); return }
        const id = await ctx.sessions.create({ workspaceId: workspace.workspaceId })
        ctx.uiWorkspace.openSession(id)
      }}
      onWorktreeRemoved={async path => {
        // Like the host's own Workspace removal: only the registration goes, its Sessions stay on disk.
        const workspace = ctx.workspaces.list.getSnapshot().items.find(item => item.path === path)
        if (workspace !== undefined) await ctx.workspaces.delete(workspace.workspaceId)
      }}
    />
      <Modal open={openDiff !== null} onClose={() => { setOpenDiff(null) }} title={t('viewDiff')} closeLabel={t('close')}
        className={css.gitDiffModal} contentClassName={css.gitDiffModalContent}>
        {openDiff !== null && <DiffTab sessionId={sessionId} cwd={cwd} diff={openDiff} />}
      </Modal>
    </>
  }
  function DiffBody({ sessionId, useSessions, useTabInfo }: PropsRuntime<'sidebar.right.pane.tab'>) {
    useLanguage()
    const cwd = useSessions(state => sessionDirectory(state.byId[sessionId]))
    const { tab } = useTabInfo()
    const value = useMemo(() => parseDiffAddress(tab.navigation.address), [tab.navigation.address])
    if (value === undefined || value.sessionId !== sessionId) return <p>{t('diffLoadError')}</p>
    return <DiffTab sessionId={sessionId} cwd={cwd} diff={value.diff} />
  }
  ctx.effect(() => {
    // ponytail: these host rows have no icon slot; recheck this DOM seam if the host changes its row markup.
    // Main checkout path for linked Worktrees, null for everything else.
    const mainByPath = new Map<string, string | null>()
    const checking = new Set<string>()
    const rowSelector = '[data-row-key^="workspace:"]'
    let live = true
    // Main checkouts already folded once on this page: they start folded, then follow the user's own toggles.
    const folded = new Set<string>()
    const clearNesting = (section: HTMLElement) => {
      if (section.hasAttribute('data-git-worktree-child')) section.hidden = false
      section.removeAttribute('data-git-worktree-child')
      section.removeAttribute('data-git-worktree-open')
      section.removeAttribute('data-git-worktree-last')
      section.style.removeProperty('order')
    }
    // ponytail: nesting is visual only (flex `order`), so DOM order still drives drag targets and the host's
    // tree semantics, and a host reorder glides to the stale order then snaps; it applies only to top-level groups
    // ("By workspace") whose main checkout is itself a Workspace. Folding the main group hides its Worktree groups.
    const nest = (sectionById: Map<string, HTMLElement>, pathById: Map<string, string>, idByPath: Map<string, string>) => {
      const nested = new Set<Element>()
      const worktreesOf = new Map<HTMLElement, HTMLElement[]>()
      for (const [id, section] of sectionById) {
        const main = mainByPath.get(pathById.get(id)!)
        const parent = typeof main === 'string' ? sectionById.get(idByPath.get(main) ?? '') : undefined
        if (parent === undefined || parent.parentElement !== section.parentElement) { clearNesting(section); continue }
        section.setAttribute('data-git-worktree-child', '')
        // A Worktree sorts right after its main checkout; equal orders keep sibling Worktrees in host order.
        section.style.order = String(2 * [...parent.parentElement!.children].indexOf(parent) + 1)
        nested.add(parent.parentElement!)
        worktreesOf.set(parent, [...worktreesOf.get(parent) ?? [], section])
      }
      for (const [parent, worktrees] of worktreesOf) {
        const row = parent.querySelector<HTMLElement>(rowSelector)!
        const key = row.dataset.rowKey!
        if (!folded.has(key)) {
          folded.add(key)
          if (row.getAttribute('aria-expanded') === 'true') row.click()
        }
        const open = row.getAttribute('aria-expanded') !== 'false'
        parent.toggleAttribute('data-git-worktree-open', open)
        worktrees.forEach((section, index) => {
          section.hidden = !open
          section.toggleAttribute('data-git-worktree-last', index === worktrees.length - 1)
        })
      }
      for (const tree of document.querySelectorAll<HTMLElement>('[data-git-worktree-tree]')) {
        if (nested.has(tree)) continue
        tree.removeAttribute('data-git-worktree-tree')
        for (const section of tree.children) if (section instanceof HTMLElement) clearNesting(section)
      }
      for (const tree of nested) {
        tree.setAttribute('data-git-worktree-tree', '')
        ;[...tree.children].forEach((section, index) => {
          if (section instanceof HTMLElement && !section.hasAttribute('data-git-worktree-child')) section.style.order = String(2 * index)
        })
      }
    }
    const sync = () => {
      const workspaces = ctx.workspaces.list.getSnapshot().items
      const pathById = new Map<string, string>(workspaces.map(workspace => [workspace.workspaceId, workspace.path]))
      const idByPath = new Map<string, string>(workspaces.map(workspace => [workspace.path, workspace.workspaceId]))
      const sectionById = new Map<string, HTMLElement>()
      for (const row of document.querySelectorAll<HTMLElement>(rowSelector)) {
        const id = row.dataset.rowKey!.slice('workspace:'.length)
        // The top-level group this row heads; a group nested by the host's tree view finds its ancestor's header first.
        const section = row.closest<HTMLElement>('[role="tree"] > *')
        if (section !== null && section.querySelector(rowSelector) === row && pathById.has(id)) sectionById.set(id, section)
        const folder = row.firstElementChild
        if (!(folder instanceof HTMLElement)) continue
        const path = pathById.get(id)
        if (path !== undefined && typeof mainByPath.get(path) === 'string') {
          folder.setAttribute('data-git-worktree-folder', '')
          folder.setAttribute('role', 'img')
          folder.setAttribute('aria-label', t('worktreeMark'))
          folder.setAttribute('title', t('worktreeMark'))
        } else if (folder.hasAttribute('data-git-worktree-folder')) {
          folder.removeAttribute('data-git-worktree-folder')
          folder.removeAttribute('role')
          folder.removeAttribute('aria-label')
          folder.removeAttribute('title')
        }
      }
      nest(sectionById, pathById, idByPath)
      for (const { path } of workspaces) {
        if (mainByPath.has(path) || checking.has(path)) continue
        checking.add(path)
        void api.gitWorktreeLinked(path).then(({ main }) => { mainByPath.set(path, main ?? null) }, () => { mainByPath.set(path, null) })
          .finally(() => { checking.delete(path); if (live) sync() })
      }
    }
    const observer = new MutationObserver(records => {
      if (records.some(record => (record.target instanceof Element && record.target.closest(rowSelector) !== null)
        || [...record.addedNodes].some(node => node instanceof Element && (node.matches(rowSelector) || node.querySelector(rowSelector) !== null)))) sync()
    })
    observer.observe(document.body, { childList: true, subtree: true, attributes: true, attributeFilter: ['aria-expanded'] })
    const unsubscribeWorkspaces = ctx.workspaces.list.subscribe(sync)
    const unsubscribeLocale = ctx.locale.subscribe(sync)
    sync()
    return () => {
      live = false
      observer.disconnect()
      unsubscribeWorkspaces()
      unsubscribeLocale()
      nest(new Map(), new Map(), new Map())
      for (const folder of document.querySelectorAll('[data-git-worktree-folder]')) {
        folder.removeAttribute('data-git-worktree-folder')
        folder.removeAttribute('role')
        folder.removeAttribute('aria-label')
        folder.removeAttribute('title')
      }
    }
  })
  function GitTitle() { useLanguage(); return <><IconBranchOutlineRegular size={16} /> {t('git')}</> }
  ctx.effect(() => ctx.slots.inject('sidebar.right.pane.tab', () => ctx.slots.register(
    { name: 'sidebar.right.pane.tab', key: 'dsh-git-sidebar' }, GitBody,
  )))
  ctx.effect(() => ctx.slots.inject('sidebar.right.pane.tab', () => ctx.slots.register(
    { name: 'sidebar.right.pane.tab', key: 'dsh-git-sidebar/diff' }, DiffBody,
  )))
  ctx.effect(() => ctx.slots.inject('sidebar.right.pane.tab.title', () => ctx.slots.register(
    { name: 'sidebar.right.pane.tab.title', key: 'dsh-git-sidebar' }, GitTitle,
  )))
}
